func netbirdArtifactStore(t *testing.T, conn *nats.Conn) jetstream.ObjectStore {
	t.Helper()
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	store, err := js.CreateObjectStore(t.Context(), jetstream.ObjectStoreConfig{Bucket: delivery.ArtifactBucket})
	if err != nil {
		t.Fatal(err)
	}
	return store
}

func stageTestNetbirdArtifacts(t *testing.T, store jetstream.ObjectStore, pin client.Pin) {
	t.Helper()
	for architecture, digest := range map[string]string{"arm64": pin.Archives.Arm64.BinarySHA256, "amd64": pin.Archives.AMD64.BinarySHA256} {
		body := netbirdArtifactELF(architecture)
		if netbirdStageDigest(body) != digest {
			t.Fatal("artifact fixture pin does not match its ELF bytes")
		}
		if _, err := store.PutBytes(t.Context(), "sha256-"+digest, body); err != nil {
			t.Fatal(err)
		}
	}
}

func netbirdArtifactELF(architecture string) []byte {
	body := netbirdStageELF("verified " + architecture + " client")
	if architecture == "arm64" {
		binary.LittleEndian.PutUint16(body[18:], 183)
	}
	return body
}

func netbirdArtifactTestPin(t *testing.T) client.Pin {
	t.Helper()
	pin := netbirdStageTestPin(t, netbirdArtifactELF("amd64"))
	pin.Archives.Arm64.BinarySHA256 = netbirdStageDigest(netbirdArtifactELF("arm64"))
	return pin
}

func netbirdArtifactTest(t *testing.T, deniedDigest string) (*netbirdRollout, client.Pin, jetstream.JetStream) {
	t.Helper()
	pin := netbirdArtifactTestPin(t)
	deniedSubject := "$O." + delivery.ArtifactBucket + ".M." + base64.URLEncoding.EncodeToString([]byte("sha256-"+deniedDigest))
	broker, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, JetStream: true, StoreDir: t.TempDir(), Users: []*server.User{
		{Username: "admin", Password: "admin"},
		{Username: "admission", Password: "admission", Permissions: &server.Permissions{
			Publish:   &server.SubjectPermission{Allow: []string{">"}, Deny: []string{deniedSubject}},
			Subscribe: &server.SubjectPermission{Allow: []string{">"}},
		}},
	}})
	if err != nil {
		t.Fatal(err)
	}
	broker.Start()
	t.Cleanup(func() { broker.Shutdown(); broker.WaitForShutdown() })
	if !broker.ReadyForConnections(5 * time.Second) {
		t.Fatal("artifact NATS did not start")
	}
	connect := func(user string) *nats.Conn {
		t.Helper()
		conn, err := nats.Connect(broker.ClientURL(), nats.UserInfo(user, user), nats.ErrorHandler(func(*nats.Conn, *nats.Subscription, error) {}))
		if err != nil {
			t.Fatal(err)
		}
		t.Cleanup(conn.Close)
		return conn
	}
	conn := connect("admin")
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	kv, err := js.CreateKeyValue(t.Context(), jetstream.KeyValueConfig{Bucket: "TS_RELEASE_CHANNEL"})
	if err != nil {
		t.Fatal(err)
	}
	r := &netbirdRollout{cell: "gru", conn: conn, fence: &releaseFence{kv: kv, fencer: &fenceLease{}}, services: &specRegistry{}, artifacts: netbirdArtifactStore(t, conn)}
	if deniedDigest != "" {
		r.conn = connect("admission")
	}
	return r, pin, js
}

func netbirdStageELF(payload string) []byte {
	wire := make([]byte, 64)
	copy(wire, "\x7fELF\x02\x01\x01")
	binary.LittleEndian.PutUint16(wire[16:], 2)
	binary.LittleEndian.PutUint16(wire[18:], 62)
	binary.LittleEndian.PutUint32(wire[20:], 1)
	binary.LittleEndian.PutUint16(wire[52:], 64)
	return append(wire, payload...)
}

func netbirdStageDigest(body []byte) string {
	digest := sha256.Sum256(body)
	return hex.EncodeToString(digest[:])
}

func netbirdStageTestPin(t *testing.T, body []byte) client.Pin {
	t.Helper()
	pin, err := client.LoadPin("../../deploy/image/image-inputs.json")
	if err != nil {
		t.Fatal(err)
	}
	pin.Archives.AMD64.BinarySHA256 = netbirdStageDigest(body)
	return pin
}

func signedNetbirdStage(t *testing.T, key ed25519.PrivateKey, request netbirdStageRequest, epoch uint64) []byte {
	t.Helper()
	payload, err := json.Marshal(request)
	if err != nil {
		t.Fatal(err)
	}
	now := time.Now().UTC()
	envelope, err := protocol.SignEnvelope(payload, protocol.EnvelopeScope{Region: "gru", Kind: netbirdStageKind,
		Actor: "ops", OperationID: "6FG8JSQDE0WD6HX997W10WK3DM", Generation: 1, Epoch: epoch}, now, now.Add(time.Minute), key)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := protocol.EncodeJSON(envelope)
	if err != nil {
		t.Fatal(err)
	}
	return wire
}

func netbirdStagePolicy(t *testing.T, root string) (signerPolicy, TrustedSignerConfig, ed25519.PrivateKey) {
	t.Helper()
	public, private := testEd25519(t, root, "operator.key")
	grant := TrustedSignerConfig{Actor: "ops", PublicKey: base64.StdEncoding.EncodeToString(public),
		Roles: []string{"ts-auth"}, Environments: []string{"production"}}
	policy, err := buildSignerPolicy(Config{NATS: natscell.Config{Cell: "gru"},
		Controller: ControllerConfig{TrustedSigners: []TrustedSignerConfig{grant}}})
	if err != nil {
		t.Fatal(err)
	}
	return policy, grant, private
}

func (l *fenceLease) ReadNetBirdState(context.Context) (authority.LogEntry, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.netbird.Sequence == 0 {
		return authority.LogEntry{}, authority.ErrNotFound
	}
	entry := l.netbird
	entry.Payload = slices.Clone(entry.Payload)
	return entry, nil
}

func (l *fenceLease) CommitNetBirdState(ctx context.Context, epoch uint64, operation string, expected uint64, wire []byte) (uint64, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if err := ctx.Err(); err != nil {
		return 0, err
	}
	if l.lost || epoch != 3 {
		return 0, authority.ErrFenced
	}
	if l.netbird.Sequence != expected {
		return 0, authority.ErrConflict
	}
	l.netbird = authority.LogEntry{Epoch: epoch, Sequence: expected + 1, OperationID: operation, Payload: slices.Clone(wire)}
	return l.netbird.Sequence, nil
}

func saveNetBirdTestRecord(ctx context.Context, n *netbirdRollout, epoch uint64, record network.Record) error {
	state, err := n.state(ctx)
	if err != nil {
		return err
	}
	next := state
	if state.Record.ID != record.ID || state.Record.Node != record.Node {
		next.Command = network.Command{}
	}
	next.Record = record
	return n.commitStateAt(ctx, epoch, &state, next)
}

func saveNetBirdTestAdmission(ctx context.Context, n *netbirdRollout, epoch uint64, record network.Record) error {
	state, err := n.state(ctx)
	if err != nil {
		return err
	}
	return n.saveRecordAt(ctx, epoch, &state, record)
}

