func (n *netbirdRollout) preflight(ctx context.Context, node string) error {
	if err := n.artifactsReady(ctx); err != nil {
		return err
	}
	spec, addresses, err := n.preflightAddresses(ctx, node)
	if err != nil {
		return err
	}
	if spec == nil || addresses[node] == "" || len(addresses) < 2 {
		return errors.New("NetBird upgrade requires a release fence and at least two granted nodes")
	}
	leader := n.services.controllerNode(n.cell, n.cfg.NATS.Instance)
	probe, err := n.status(ctx, leader)
	if err != nil {
		return err
	}
	if probe.Missing || probe.Version == "" || !probe.Connected {
		return errors.New("NetBird probing leader has no working mesh client; restore verified bootstrap enrollment over OCI before draining")
	}
	// Refuse a cell already being drained by another rollout. Quorum guards
	// in fence.fence still serialize every actual LB removal.
	keys, err := n.fence.keys(ctx, fencedKey("*"))
	if err != nil {
		return err
	}
	for _, key := range keys {
		record, found, err := n.fence.record(ctx, strings.TrimPrefix(key, fencedKey("")))
		if err != nil {
			return err
		}
		if found && slices.ContainsFunc(record.holders(), func(holder string) bool { return holder != netbirdHold }) {
			return fmt.Errorf("NetBird rollout waits for existing fence on %s", strings.TrimPrefix(key, fencedKey("")))
		}
	}
	if n.nodes != nil && n.nodes.cluster != nil {
		if err := n.nodes.cluster(ctx, node); err != nil {
			return err
		}
	}
	// Verify ordinary SSH on the OCI VCN address. We never change sshd,
	// networking, security lists, public IPs or this independent path.
	if err := n.recoverySSH(ctx, node, addresses[node]); err != nil {
		return fmt.Errorf("OCI SSH recovery path for %s is unavailable: %w", node, err)
	}
	selected, err := n.status(ctx, node)
	if err != nil {
		return err
	}
	bootstrapRemote := selected.Missing && selected.Version == "" && node != n.services.controllerNode(n.cell, n.cfg.NATS.Instance)
	for candidate := range addresses {
		status, err := n.status(ctx, candidate)
		if err != nil {
			return err
		}
		if status.Pending != "" || status.Error != "" {
			return fmt.Errorf("NetBird preflight %s has an unresolved worker operation", candidate)
		}
		// Several joining nodes may need their first authenticated install.
		// Only explicit executable absence can skip mesh health; a failed
		// observation of an installed daemon must still hold the rollout.
		if status.Missing && status.Version == "" {
			continue
		}
		// An unchanged installed leader can admit its first missing peer.
		// Confirmation still proves that peer's traffic over the mesh.
		if err := n.healthyMesh(ctx, candidate, status, time.Time{}, !bootstrapRemote); err != nil {
			return fmt.Errorf("NetBird preflight %s: %w", candidate, err)
		}
	}
	return nil
}

func (n *netbirdRollout) artifactsReady(ctx context.Context) error {
	ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()
	if err := ctx.Err(); err != nil {
		return err
	}
	pin, err := n.target(ctx)
	if err != nil {
		return err
	}
	if pin == nil || n.artifacts == nil {
		return errors.New("NetBird artifacts are not configured")
	}
	if n.conn == nil {
		return errors.New("NetBird artifact admission requires the controller's NATS connection")
	}
	js, err := jetstream.New(n.conn)
	if err != nil {
		return err
	}
	legacy, err := n.conn.JetStream()
	if err != nil {
		return err
	}
	binaries := [2]struct{ architecture, digest string }{
		{"arm64", pin.Pin.Archives.Arm64.BinarySHA256},
		{"amd64", pin.Pin.Archives.AMD64.BinarySHA256},
	}
	var metadata [2]*nats.RawStreamMsg
	for i, binary := range binaries {
		name := "sha256-" + binary.digest
		subject := "$O." + delivery.ArtifactBucket + ".M." + base64.URLEncoding.EncodeToString([]byte(name))
		meta, err := legacy.GetLastMsg("OBJ_"+delivery.ArtifactBucket, subject, nats.Context(ctx))
		if err != nil {
			return fmt.Errorf("NetBird artifact %s is not staged; no node will be drained: %w", binary.digest, err)
		}
		var info jetstream.ObjectInfo
		if json.Unmarshal(meta.Data, &info) != nil || info.Name != name || info.Bucket != delivery.ArtifactBucket ||
			info.Deleted || info.Size < 64 || info.Size > client.MaxBinaryBytes {
			return fmt.Errorf("NetBird artifact %s is not staged; no node will be drained", binary.digest)
		}
		n.artifactMu.Lock()
		// Object-store writes replace metadata for changed chunks; direct
		// administrative chunk mutation must not bypass that contract.
		verified := bytes.Equal(n.verifiedMetadata[i], meta.Data)
		n.artifactMu.Unlock()
		if !verified {
			if err := verifyNetBirdArtifactContents(ctx, binary.digest, binary.architecture, func(dst io.Writer) error {
				return artifact.ReadVerifiedAuthoritative(ctx, js, &info, delivery.ArtifactBucket, name, binary.digest,
					int64(info.Size), client.MaxBinaryBytes, dst)
			}); err != nil {
				return fmt.Errorf("verify NetBird artifact %s (%s) before drain: %w", binary.digest, binary.architecture, err)
			}
			n.artifactMu.Lock()
			n.verifiedMetadata[i] = meta.Data
			n.artifactMu.Unlock()
		}
		metadata[i] = meta
	}
	// Fence collectors that selected these objects before the pin became active.
	for i, binary := range binaries {
		if err := artifact.Touch(ctx, legacy, delivery.ArtifactBucket, "sha256-"+binary.digest); err != nil {
			return fmt.Errorf("retain NetBird artifact %s before drain: %w", binary.digest, err)
		}
		meta, err := legacy.GetLastMsg("OBJ_"+delivery.ArtifactBucket, metadata[i].Subject, nats.Context(ctx))
		if err != nil {
			return err
		}
		// Touch keeps the bytes unchanged; replacement requires fresh verification.
		if !bytes.Equal(meta.Data, metadata[i].Data) {
			return fmt.Errorf("retain NetBird artifact %s before drain: %w", binary.digest, artifact.ErrChanged)
		}
	}
	return ctx.Err()
}

func (n *netbirdRollout) artifactsInUse(ctx context.Context) ([]delivery.ArtifactUse, error) {
	var uses []delivery.ArtifactUse
	add := func(pin *cellspec.NetBird) {
		if pin != nil {
			for _, digest := range []string{pin.Pin.Archives.Arm64.BinarySHA256, pin.Pin.Archives.AMD64.BinarySHA256} {
				uses = append(uses, delivery.ArtifactUse{Digest: digest, Role: "netbird", Environment: n.cell})
			}
		}
	}
	add(n.services.netbird())
	var record network.Record
	if err := n.load(ctx, netbirdRecordKey, &record); err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	if record.ID != "" && record.Phase != "done" {
		add(&cellspec.NetBird{Pin: record.Target.Pin})
	}
	return uses, nil
}

func (r *specRegistry) netbird() *cellspec.NetBird {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.current.NetBird
}

// A spec amendment cannot abandon a node already drained or changed. Finish
// its persisted target before using the new pin or disabling management.
func (n *netbirdRollout) target(ctx context.Context) (*cellspec.NetBird, error) {
	var record network.Record
	if err := n.load(ctx, netbirdRecordKey, &record); err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	if record.ID != "" && record.Phase != "done" && (record.Phase != "failed" || !record.RecoveryComplete) {
		return &cellspec.NetBird{Pin: record.Target.Pin, Enrollment: record.Target.Enrollment}, nil
	}
	return n.services.netbird(), nil
}

type netbirdRollout struct {
	cell             string
	fence            *releaseFence
	services         *specRegistry
	nodes            *nodeOps
	key              ed25519.PrivateKey
	cfg              Config
	fleet            oci.Fleet
	artifacts        jetstream.ObjectStore
	conn             *nats.Conn
	runtime          *natscell.Runtime
	managedAddresses map[string]string
	observed         time.Time
	artifactMu       sync.Mutex
	verifiedMetadata [2][]byte
}

func (n *netbirdRollout) load(ctx context.Context, key string, value any) error {
	if key == netbirdRecordKey || strings.HasPrefix(key, "netbird.command.") {
		return n.loadIntent(ctx, key, value)
	}
	return n.fence.loadJSON(ctx, key, value)
}

func (n *netbirdRollout) saveAt(ctx context.Context, epoch uint64, key string, value any) error {
	if !strings.HasPrefix(key, "netbird.status.") {
		return errors.New("NetBird intent requires a conditional authority commit")
	}
	wire, err := json.Marshal(value)
	if err != nil {
		return err
	}
	if err := n.fence.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err = n.fence.kv.Put(ctx, key, wire)
	return err
}

func (state netbirdState) commandFor(node string) (network.Command, bool, error) {
	command := state.Command
	if state.Record.Node != node || command.ID == "" || !netbirdCommandAllowed(state.Record, command.Action) {
		return network.Command{}, false, nil
	}
	if command.Transaction != state.Record.ID || command.ID != network.CommandID(state.Record.ID, command.Action) ||
		network.Hash(command.Target) != network.Hash(state.Record.Target) {
		return network.Command{}, false, errors.New("NetBird command does not match the active transaction")
	}
	return command, true, nil
}

func readNetBirdState(ctx context.Context, reader netbirdStateReader) (netbirdState, error) {
	entry, err := reader.ReadNetBirdState(ctx)
	if errors.Is(err, authority.ErrNotFound) {
		return netbirdState{}, nil
	}
	if err != nil {
		return netbirdState{}, err
	}
	return decodeNetBirdState(entry)
}

func decodeNetBirdState(entry authority.LogEntry) (netbirdState, error) {
	var state netbirdState
	if entry.Sequence == 0 || entry.Epoch == 0 {
		return state, errors.New("invalid NetBird journal revision")
	}
	if err := json.Unmarshal(entry.Payload, &state, json.RejectUnknownMembers(true)); err != nil {
		return state, err
	}
	if (state.Record.ID != "" || state.Record.Phase != "" || state.Record.Node != "") && !entityid.Valid(state.Record.ID) {
		return state, errors.New("invalid NetBird journal identity")
	}
	state.Revision = entry.Sequence
	return state, nil
}

func (n *netbirdRollout) state(ctx context.Context) (netbirdState, error) {
	reader, ok := n.fence.fencer.(netbirdStateReader)
	if !ok {
		return netbirdState{}, errors.New("NetBird requires an authority journal reader")
	}
	return readNetBirdState(ctx, reader)
}

func (n *netbirdRollout) commitStateAt(ctx context.Context, epoch uint64, state *netbirdState, next netbirdState) error {
	store, ok := n.fence.fencer.(netbirdStateStore)
	if !ok {
		return errors.New("NetBird requires an authority journal writer")
	}
	if (next.Record.ID != "" || next.Record.Phase != "" || next.Record.Node != "") && !entityid.Valid(next.Record.ID) {
		return errors.New("invalid NetBird journal identity")
	}
	original, err := json.Marshal(*state, json.Deterministic(true))
	if err != nil {
		return err
	}
	wire, err := json.Marshal(next, json.Deterministic(true))
	if err != nil {
		return err
	}
	expected, operation := state.Revision, entityid.New()
	for attempt := range 3 {
		revision, err := store.CommitNetBirdState(ctx, epoch, operation, expected, wire)
		if err == nil {
			next.Revision = revision
			*state = next
			return nil
		}
		if !errors.Is(err, authority.ErrConflict) || attempt == 2 {
			return err
		}
		current, err := readNetBirdState(ctx, store)
		if err != nil {
			return err
		}
		currentWire, err := json.Marshal(current, json.Deterministic(true))
		if err != nil {
			return err
		}
		// Issuance changes only the revision; a changed intent invalidates
		// the original tick's health, drain and return decisions.
		if !bytes.Equal(original, currentWire) {
			return authority.ErrConflict
		}
		expected = current.Revision
	}
	return authority.ErrConflict
}

func (n *netbirdRollout) sendAt(ctx context.Context, epoch uint64, state *netbirdState, node string, command network.Command) error {
	if state.Revision == 0 || state.Record.Node != node || state.Record.ID != command.Transaction ||
		command.ID != network.CommandID(state.Record.ID, command.Action) || network.Hash(command.Target) != network.Hash(state.Record.Target) ||
		!netbirdCommandAllowed(state.Record, command.Action) {
		return errors.New("NetBird command does not match its journal snapshot")
	}
	next := *state
	next.Command = command
	return n.commitStateAt(ctx, epoch, state, next)
}

func (n *netbirdRollout) loadIntent(ctx context.Context, key string, value any) error {
	state, err := n.state(ctx)
	if err != nil {
		return err
	}
	if state.Revision == 0 {
		return os.ErrNotExist
	}
	var intent any = state.Record
	if key != netbirdRecordKey {
		if key != "netbird.command."+state.Record.Node {
			return os.ErrNotExist
		}
		command, found, err := state.commandFor(state.Record.Node)
		if err != nil {
			return err
		}
		if !found {
			return os.ErrNotExist
		}
		intent = command
	}
	wire, err := json.Marshal(intent)
	if err != nil {
		return err
	}
	return json.Unmarshal(wire, value, json.RejectUnknownMembers(true))

func ReadVerified(ctx context.Context, js jetstream.JetStream, store interface {
	GetInfo(context.Context, string, ...jetstream.GetObjectInfoOpt) (*jetstream.ObjectInfo, error)
}, bucket, name, digest string, signedSize, maxBytes int64, dst io.Writer) error {
	if js == nil || store == nil || dst == nil || signedSize <= 0 || signedSize > maxBytes || len(digest) != 64 {
		return fmt.Errorf("%w: reader arguments", ErrInvalid)
	}
	info, err := store.GetInfo(ctx, name)
	if err != nil {
		return fmt.Errorf("inspect artifact: %w", err)
	}
	if err := validateMetadata(info, bucket, name, signedSize); err != nil {
		return err
	}
	stream, err := js.Stream(ctx, "OBJ_"+bucket)
	if err != nil {
		return fmt.Errorf("bind artifact readback stream: %w", err)
	}
	return verifyChunks(ctx, info, bucket, digest, signedSize, dst, func(ctx context.Context, sequence uint64, subject string) (*jetstream.RawStreamMsg, error) {
		return stream.GetMsg(ctx, sequence, jetstream.WithGetMsgSubject(subject))
	})
}

// ReadVerifiedAuthoritative verifies captured leader metadata using standard
// MSG.GET chunk reads, so a stale replica cannot authorize corruption repair.
// Callers must discard dst if this function returns an error.
func ReadVerifiedAuthoritative(ctx context.Context, js jetstream.JetStream, info *jetstream.ObjectInfo,
	bucket, name, digest string, signedSize, maxBytes int64, dst io.Writer,
) error {
	if js == nil || js.Conn() == nil || dst == nil || signedSize <= 0 || signedSize > maxBytes || len(digest) != 64 {
		return fmt.Errorf("%w: reader arguments", ErrInvalid)
	}
	if err := validateMetadata(info, bucket, name, signedSize); err != nil {
		return err
	}
	options := js.Options()
	prefix := options.APIPrefix
	if options.Domain != "" {
		prefix = "$JS." + options.Domain + ".API."
	} else if prefix == "" {
		prefix = jetstream.DefaultAPIPrefix
	}
	apiSubject := strings.TrimSuffix(prefix, ".") + ".STREAM.MSG.GET.OBJ_" + bucket
	if _, bounded := ctx.Deadline(); !bounded && options.DefaultTimeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, options.DefaultTimeout)
		defer cancel()
	}
	return verifyChunks(ctx, info, bucket, digest, signedSize, dst, func(ctx context.Context, sequence uint64, subject string) (*jetstream.RawStreamMsg, error) {
		request, err := json.Marshal(struct {
			Sequence uint64 `json:"seq"`
			Subject  string `json:"next_by_subj"`
		}{sequence, subject})
		if err != nil {
			return nil, err
		}
		message, err := js.Conn().RequestWithContext(ctx, apiSubject, request)
		if err != nil {
			return nil, err
		}
		var response struct {
			Error   *jetstream.APIError `json:"error"`
			Message *struct {
				Subject  string `json:"subject"`
				Sequence uint64 `json:"seq"`
				Data     []byte `json:"data"`
			} `json:"message"`
		}
		if err := json.Unmarshal(message.Data, &response); err != nil {
			return nil, err
		}
		if response.Error != nil {
			return nil, response.Error
		}
		if response.Message == nil {
			return nil, jetstream.ErrInvalidJetStreamResponse
		}
		return &jetstream.RawStreamMsg{Subject: response.Message.Subject, Sequence: response.Message.Sequence,
			Data: response.Message.Data}, nil
	})
}

func validateMetadata(info *jetstream.ObjectInfo, bucket, name string, signedSize int64) error {
	if info == nil || info.Name != name || info.Bucket != bucket || info.Deleted ||
		info.Opts != nil && info.Opts.Link != nil || info.Size != uint64(signedSize) ||
		info.NUID == "" || info.Chunks == 0 || uint64(info.Chunks) > uint64(signedSize) {
		return fmt.Errorf("%w: artifact object metadata", ErrInvalid)
	}
	return nil
}

func verifyChunks(ctx context.Context, info *jetstream.ObjectInfo, bucket, digest string, sizeLimit int64, dst io.Writer,
	get func(context.Context, uint64, string) (*jetstream.RawStreamMsg, error)) error {
	if info == nil || info.NUID == "" || info.Chunks == 0 || sizeLimit <= 0 ||
		uint64(info.Chunks) > uint64(sizeLimit) {
		return fmt.Errorf("%w: artifact chunk metadata", ErrInvalid)
	}
	storedDigest, err := jetstream.DecodeObjectDigest(info.Digest)
	if err != nil || len(storedDigest) != sha256.Size {
		return fmt.Errorf("%w: artifact object digest", ErrInvalid)
	}
	subject := "$O." + bucket + ".C." + info.NUID
	h := sha256.New()
	var size int64
	sequence := uint64(1)
	for range info.Chunks {
		if err := ctx.Err(); err != nil {
			return err
		}
		message, err := get(ctx, sequence, subject)
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			return fmt.Errorf("artifact chunk is not visible: %w", jetstream.ErrObjectNotFound)
		}
		if err != nil {
			return fmt.Errorf("read artifact chunk: %w", err)
		}
		if message == nil || message.Subject != subject || message.Sequence < sequence ||
			message.Sequence == ^uint64(0) || len(message.Data) == 0 || int64(len(message.Data)) > sizeLimit-size {
			return fmt.Errorf("%w: artifact chunk sequence or size", ErrInvalid)
		}
		if _, err := dst.Write(message.Data); err != nil {
			return fmt.Errorf("spool artifact chunk: %w", err)
		}
		_, _ = h.Write(message.Data)
		size += int64(len(message.Data))
		sequence = message.Sequence + 1
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	extra, err := get(ctx, sequence, subject)
	if err == nil || extra != nil {
		return fmt.Errorf("%w: artifact has extra chunks", ErrInvalid)
	}
	if !errors.Is(err, jetstream.ErrMsgNotFound) {
		return fmt.Errorf("check artifact chunk count: %w", err)
	}
	actual := h.Sum(nil)
	if size != sizeLimit || hex.EncodeToString(actual) != digest || !bytes.Equal(actual, storedDigest) {
		return fmt.Errorf("%w: artifact bytes differ from signed digest", ErrInvalid)
	}
	return nil
}

func Touch(ctx context.Context, js nats.JetStreamContext, bucket, name string) error {
	subject := metaSubject(bucket, name)
	meta, err := liveMeta(ctx, js, bucket, subject, name)
	if err != nil {
		return err
	}
	err = publishMeta(ctx, js, subject, meta.Data, meta.Sequence)
	if !errors.Is(err, ErrChanged) {
		return err
	}
	// Another write since the read fences a collector just the same,
	// unless it deleted the object.
	_, err = liveMeta(ctx, js, bucket, subject, name)
	return err
}

// liveMeta reads an object's metadata from the stream leader and refuses a
// deleted object.
func liveMeta(ctx context.Context, js nats.JetStreamContext, bucket, subject, name string) (*nats.RawStreamMsg, error) {
	meta, err := js.GetLastMsg("OBJ_"+bucket, subject, nats.Context(ctx))
	if errors.Is(err, nats.ErrMsgNotFound) {
		return nil, jetstream.ErrObjectNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("read artifact metadata: %w", err)
	}
	var info jetstream.ObjectInfo
	if err := json.Unmarshal(meta.Data, &info); err != nil || info.Name != name {
		return nil, fmt.Errorf("%w: artifact object metadata", ErrInvalid)
	}
	if info.Deleted {
		return nil, jetstream.ErrObjectNotFound
	}
	return meta, nil

func metaSubject(bucket, name string) string {
	return "$O." + bucket + ".M." + base64.URLEncoding.EncodeToString([]byte(name))
}

func publishMeta(ctx context.Context, js nats.JetStreamContext, subject string, data []byte, sequence uint64) error {
	msg := nats.NewMsg(subject)
	msg.Header.Set(nats.MsgRollup, nats.MsgRollupSubject)
	msg.Data = data
	_, err := js.PublishMsg(msg, nats.Context(ctx), nats.ExpectLastSequencePerSubject(sequence))
	if apiErr, ok := errors.AsType[*nats.APIError](err); ok && (apiErr.ErrorCode == nats.JSErrCodeStreamWrongLastSequence ||
		apiErr.ErrorCode == nats.JSErrCodeStreamWrongLastSequenceConstant) {
		return ErrChanged
	}
	return err
}

func VerifyBinary(path, expected, architecture string) error {
	return verifyBinaryLimit(path, expected, architecture, MaxBinaryBytes)
}

func verifyBinaryLimit(path, expected, architecture string, maximum int64) error {
	if !SHA256Pattern.MatchString(expected) {
		return errors.New("NetBird binary SHA-256 must be 64 lowercase hex characters")
	}
	f, e := openBoundedFileLimit(path, 64, maximum)
	if e != nil {
		return e
	}
	defer f.Close()
	var header [64]byte
	if _, e = io.ReadFull(f, header[:]); e != nil {
		return e
	}
	machine := uint16(183)
	if architecture == "amd64" {
		machine = 62
	} else if architecture != "arm64" {
		return errors.New("unsupported architecture")
	}
	if string(header[:7]) != "\x7fELF\x02\x01\x01" || (binary.LittleEndian.Uint16(header[16:]) != 2 && binary.LittleEndian.Uint16(header[16:]) != 3) || binary.LittleEndian.Uint16(header[18:]) != machine || binary.LittleEndian.Uint32(header[20:]) != 1 || binary.LittleEndian.Uint16(header[52:]) != 64 {
		return fmt.Errorf("NetBird binary must be an ELF64 little-endian %s executable", architecture)
	}
	h := sha256.New()
	h.Write(header[:])
	n, e := io.Copy(h, io.LimitReader(f, maximum+1-int64(len(header))))
	if e != nil {
		return e
	}
	if n+int64(len(header)) > maximum {
		return fmt.Errorf("NetBird binary exceeds %d bytes", maximum)
	}
	if hex.EncodeToString(h.Sum(nil)) != expected {
		return errors.New("NetBird binary bytes differ from the pinned SHA-256")
	}
	return nil
}

