func netbirdStagePin(services *specRegistry, request netbirdStageRequest) (string, error) {
	if services == nil || request.Size < 64 || request.Size > client.MaxBinaryBytes || !client.SHA256Pattern.MatchString(request.Digest) {
		return "", errors.New("invalid NetBird staging request")
	}
	pin := services.netbird()
	if pin == nil {
		return "", errors.New("cell spec has no NetBird pin")
	}
	if err := client.ValidatePin(pin.Pin); err != nil {
		return "", err
	}
	archive, err := pin.Pin.Archive(request.Architecture)
	if err != nil {
		return "", err
	}
	if archive.BinarySHA256 != request.Digest {
		return "", errors.New("NetBird binary SHA-256 is not authorized by the active cell pin")
	}
	return pin.Pin.Version, nil
}

func verifyNetBirdArtifact(ctx context.Context, js jetstream.JetStream, store jetstream.ObjectStore,
	digest, architecture string, size int64,
) error {
	return verifyNetBirdArtifactContents(ctx, digest, architecture, func(dst io.Writer) error {
		return artifact.ReadVerified(ctx, js, store, delivery.ArtifactBucket, "sha256-"+digest, digest,
			size, client.MaxBinaryBytes, dst)
	})
}

func verifyNetBirdArtifactContents(ctx context.Context, digest, architecture string, read func(io.Writer) error) error {
	file, err := os.CreateTemp("", "ts-netbird-verify-*")
	if err != nil {
		return err
	}
	defer os.Remove(file.Name())
	defer file.Close()
	if err := read(file); err != nil {
		return err
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if err := client.VerifyBinary(file.Name(), digest, architecture); err != nil {
		return err
	}
	return ctx.Err()
}

// serveNetBirdStage authorizes exact public upstream bytes with the active
// signed cell pin. It creates no build-source claim or workload admission.
// Requests use the existing authenticated operator registration transport.
func serveNetBirdStage(ctx context.Context, wire []byte, policy signerPolicy, fencer authority.Fencer,
	services *specRegistry, conn *nats.Conn,
) (netbirdStageReply, error) {
	envelope, _, err := verifyCellRequest(wire, policy, fencer)
	if err != nil {
		return netbirdStageReply{}, err
	}
	if envelope.Kind != netbirdStageKind {
		return netbirdStageReply{}, errors.New("invalid NetBird staging request kind")
	}
	var request netbirdStageRequest
	if err := protocol.DecodeStrict(envelope.Payload, &request, 4096); err != nil {
		return netbirdStageReply{}, err
	}
	version, err := netbirdStagePin(services, request)
	if err != nil {
		return netbirdStageReply{}, err
	}
	if err := fencer.Guard(ctx, envelope.Epoch); err != nil {
		return netbirdStageReply{}, err
	}
	reply := netbirdStageReply{Version: version, Architecture: request.Architecture, Digest: request.Digest, Size: request.Size}
	if !request.Verify {
		return reply, nil
	}
	js, err := jetstream.New(conn)
	if err != nil {
		return netbirdStageReply{}, err
	}
	store, err := js.ObjectStore(ctx, delivery.ArtifactBucket)
	if err != nil {
		return netbirdStageReply{}, err
	}
	name := "sha256-" + request.Digest
	if err := verifyNetBirdArtifact(ctx, js, store, request.Digest, request.Architecture, request.Size); err != nil {
		return netbirdStageReply{}, err
	}
	if _, err := netbirdStagePin(services, request); err != nil {
		return netbirdStageReply{}, err
	}
	if err := fencer.Guard(ctx, envelope.Epoch); err != nil {
		return netbirdStageReply{}, err
	}
	legacy, err := conn.JetStream()
	if err != nil {
		return netbirdStageReply{}, err
	}
	// Even an existing object is touched: a collector that chose it before
	// this pin became active must not delete the new reference afterward.
	if err := artifact.Touch(ctx, legacy, delivery.ArtifactBucket, name); err != nil {
		return netbirdStageReply{}, err
	}
	if err := fencer.Guard(ctx, envelope.Epoch); err != nil {
		return netbirdStageReply{}, err
	}
	if _, err := netbirdStagePin(services, request); err != nil {
		return netbirdStageReply{}, err
	}
	reply.Staged = true
	return reply, nil
}

func ReadVerified(ctx context.Context, js jetstream.JetStream, store interface {
	GetInfo(context.Context, string, ...jetstream.GetObjectInfoOpt) (*jetstream.ObjectInfo, error)
}, bucket, name, digest string, signedSize, maxBytes int64, dst io.Writer) error {
	if js == nil || store == nil || dst == nil || signedSize <= 0 || signedSize > maxBytes || len(digest) != 64 {
		return fmt.Errorf("%w: reader arguments", ErrInvalid)
	}
	info, err := store.GetInfo(ctx, name)
	if err != nil {
		return fmt.Errorf("inspect artifact: %w", err)
	}
	if err := validateMetadata(info, bucket, name, signedSize); err != nil {
		return err
	}
	stream, err := js.Stream(ctx, "OBJ_"+bucket)
	if err != nil {
		return fmt.Errorf("bind artifact readback stream: %w", err)
	}
	return verifyChunks(ctx, info, bucket, digest, signedSize, dst, func(ctx context.Context, sequence uint64, subject string) (*jetstream.RawStreamMsg, error) {
		return stream.GetMsg(ctx, sequence, jetstream.WithGetMsgSubject(subject))
	})
}

// ReadVerifiedAuthoritative verifies captured leader metadata using standard
// MSG.GET chunk reads, so a stale replica cannot authorize corruption repair.
// Callers must discard dst if this function returns an error.
func ReadVerifiedAuthoritative(ctx context.Context, js jetstream.JetStream, info *jetstream.ObjectInfo,
	bucket, name, digest string, signedSize, maxBytes int64, dst io.Writer,
) error {
	if js == nil || js.Conn() == nil || dst == nil || signedSize <= 0 || signedSize > maxBytes || len(digest) != 64 {
		return fmt.Errorf("%w: reader arguments", ErrInvalid)
	}
	if err := validateMetadata(info, bucket, name, signedSize); err != nil {
		return err
	}
	options := js.Options()
	prefix := options.APIPrefix
	if options.Domain != "" {
		prefix = "$JS." + options.Domain + ".API."
	} else if prefix == "" {
		prefix = jetstream.DefaultAPIPrefix
	}
	apiSubject := strings.TrimSuffix(prefix, ".") + ".STREAM.MSG.GET.OBJ_" + bucket
	if _, bounded := ctx.Deadline(); !bounded && options.DefaultTimeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, options.DefaultTimeout)
		defer cancel()
	}
	return verifyChunks(ctx, info, bucket, digest, signedSize, dst, func(ctx context.Context, sequence uint64, subject string) (*jetstream.RawStreamMsg, error) {
		request, err := json.Marshal(struct {
			Sequence uint64 `json:"seq"`
			Subject  string `json:"next_by_subj"`
		}{sequence, subject})
		if err != nil {
			return nil, err
		}
		message, err := js.Conn().RequestWithContext(ctx, apiSubject, request)
		if err != nil {
			return nil, err
		}
		var response struct {
			Error   *jetstream.APIError `json:"error"`
			Message *struct {
				Subject  string `json:"subject"`
				Sequence uint64 `json:"seq"`
				Data     []byte `json:"data"`
			} `json:"message"`
		}
		if err := json.Unmarshal(message.Data, &response); err != nil {
			return nil, err
		}
		if response.Error != nil {
			return nil, response.Error
		}
		if response.Message == nil {
			return nil, jetstream.ErrInvalidJetStreamResponse
		}
		return &jetstream.RawStreamMsg{Subject: response.Message.Subject, Sequence: response.Message.Sequence,
			Data: response.Message.Data}, nil
	})
}

func validateMetadata(info *jetstream.ObjectInfo, bucket, name string, signedSize int64) error {
	if info == nil || info.Name != name || info.Bucket != bucket || info.Deleted ||
		info.Opts != nil && info.Opts.Link != nil || info.Size != uint64(signedSize) ||
		info.NUID == "" || info.Chunks == 0 || uint64(info.Chunks) > uint64(signedSize) {
		return fmt.Errorf("%w: artifact object metadata", ErrInvalid)
	}
	return nil
}

func verifyChunks(ctx context.Context, info *jetstream.ObjectInfo, bucket, digest string, sizeLimit int64, dst io.Writer,
	get func(context.Context, uint64, string) (*jetstream.RawStreamMsg, error)) error {
	if info == nil || info.NUID == "" || info.Chunks == 0 || sizeLimit <= 0 ||
		uint64(info.Chunks) > uint64(sizeLimit) {
		return fmt.Errorf("%w: artifact chunk metadata", ErrInvalid)
	}
	storedDigest, err := jetstream.DecodeObjectDigest(info.Digest)
	if err != nil || len(storedDigest) != sha256.Size {
		return fmt.Errorf("%w: artifact object digest", ErrInvalid)
	}
	subject := "$O." + bucket + ".C." + info.NUID
	h := sha256.New()
	var size int64
	sequence := uint64(1)
	for range info.Chunks {
		if err := ctx.Err(); err != nil {
			return err
		}
		message, err := get(ctx, sequence, subject)
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			return fmt.Errorf("artifact chunk is not visible: %w", jetstream.ErrObjectNotFound)
		}
		if err != nil {
			return fmt.Errorf("read artifact chunk: %w", err)
		}
		if message == nil || message.Subject != subject || message.Sequence < sequence ||
			message.Sequence == ^uint64(0) || len(message.Data) == 0 || int64(len(message.Data)) > sizeLimit-size {
			return fmt.Errorf("%w: artifact chunk sequence or size", ErrInvalid)
		}
		if _, err := dst.Write(message.Data); err != nil {
			return fmt.Errorf("spool artifact chunk: %w", err)
		}
		_, _ = h.Write(message.Data)
		size += int64(len(message.Data))
		sequence = message.Sequence + 1
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	extra, err := get(ctx, sequence, subject)
	if err == nil || extra != nil {
		return fmt.Errorf("%w: artifact has extra chunks", ErrInvalid)
	}
	if !errors.Is(err, jetstream.ErrMsgNotFound) {
		return fmt.Errorf("check artifact chunk count: %w", err)
	}
	actual := h.Sum(nil)
	if size != sizeLimit || hex.EncodeToString(actual) != digest || !bytes.Equal(actual, storedDigest) {
		return fmt.Errorf("%w: artifact bytes differ from signed digest", ErrInvalid)
	}
	return nil
}

func VerifyBinary(path, expected, architecture string) error {
	return verifyBinaryLimit(path, expected, architecture, MaxBinaryBytes)
}

func verifyBinaryLimit(path, expected, architecture string, maximum int64) error {
	if !SHA256Pattern.MatchString(expected) {
		return errors.New("NetBird binary SHA-256 must be 64 lowercase hex characters")
	}
	f, e := openBoundedFileLimit(path, 64, maximum)
	if e != nil {
		return e
	}
	defer f.Close()
	var header [64]byte
	if _, e = io.ReadFull(f, header[:]); e != nil {
		return e
	}
	machine := uint16(183)
	if architecture == "amd64" {
		machine = 62
	} else if architecture != "arm64" {
		return errors.New("unsupported architecture")
	}
	if string(header[:7]) != "\x7fELF\x02\x01\x01" || (binary.LittleEndian.Uint16(header[16:]) != 2 && binary.LittleEndian.Uint16(header[16:]) != 3) || binary.LittleEndian.Uint16(header[18:]) != machine || binary.LittleEndian.Uint32(header[20:]) != 1 || binary.LittleEndian.Uint16(header[52:]) != 64 {
		return fmt.Errorf("NetBird binary must be an ELF64 little-endian %s executable", architecture)
	}
	h := sha256.New()
	h.Write(header[:])
	n, e := io.Copy(h, io.LimitReader(f, maximum+1-int64(len(header))))
	if e != nil {
		return e
	}
	if n+int64(len(header)) > maximum {
		return fmt.Errorf("NetBird binary exceeds %d bytes", maximum)
	}
	if hex.EncodeToString(h.Sum(nil)) != expected {
		return errors.New("NetBird binary bytes differ from the pinned SHA-256")
	}
	return nil
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

