func netbirdStagePin(services *specRegistry, request netbirdStageRequest) (string, error) {
	if services == nil || request.Size < 64 || request.Size > client.MaxBinaryBytes || !client.SHA256Pattern.MatchString(request.Digest) {
		return "", errors.New("invalid NetBird staging request")
	}
	pin := services.netbird()
	if pin == nil {
		return "", errors.New("cell spec has no NetBird pin")
	}
	if err := client.ValidatePin(pin.Pin); err != nil {
		return "", err
	}
	archive, err := pin.Pin.Archive(request.Architecture)
	if err != nil {
		return "", err
	}
	if archive.BinarySHA256 != request.Digest {
		return "", errors.New("NetBird binary SHA-256 is not authorized by the active cell pin")
	}
	return pin.Pin.Version, nil
}

func verifyNetBirdArtifact(ctx context.Context, js jetstream.JetStream, store jetstream.ObjectStore,
	digest, architecture string, size int64,
) error {
	return verifyNetBirdArtifactContents(ctx, digest, architecture, func(dst io.Writer) error {
		return artifact.ReadVerified(ctx, js, store, delivery.ArtifactBucket, "sha256-"+digest, digest,
			size, client.MaxBinaryBytes, dst)
	})
}

func verifyNetBirdArtifactContents(ctx context.Context, digest, architecture string, read func(io.Writer) error) error {
	file, err := os.CreateTemp("", "ts-netbird-verify-*")
	if err != nil {
		return err
	}
	defer os.Remove(file.Name())
	defer file.Close()
	if err := read(file); err != nil {
		return err
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if err := client.VerifyBinary(file.Name(), digest, architecture); err != nil {
		return err
	}
	return ctx.Err()
}

// serveNetBirdStage authorizes exact public upstream bytes with the active
// signed cell pin. It creates no build-source claim or workload admission.
// Requests use the existing authenticated operator registration transport.
func serveNetBirdStage(ctx context.Context, wire []byte, policy signerPolicy, fencer authority.Fencer,
	services *specRegistry, conn *nats.Conn,
) (netbirdStageReply, error) {
	envelope, _, err := verifyCellRequest(wire, policy, fencer)
	if err != nil {
		return netbirdStageReply{}, err
	}
	if envelope.Kind != netbirdStageKind {
		return netbirdStageReply{}, errors.New("invalid NetBird staging request kind")
	}
	var request netbirdStageRequest
	if err := protocol.DecodeStrict(envelope.Payload, &request, 4096); err != nil {
		return netbirdStageReply{}, err
	}
	version, err := netbirdStagePin(services, request)
	if err != nil {
		return netbirdStageReply{}, err
	}
	if err := fencer.Guard(ctx, envelope.Epoch); err != nil {
		return netbirdStageReply{}, err
	}
	reply := netbirdStageReply{Version: version, Architecture: request.Architecture, Digest: request.Digest, Size: request.Size}
	if !request.Verify {
		return reply, nil
	}
	js, err := jetstream.New(conn)
	if err != nil {
		return netbirdStageReply{}, err
	}
	store, err := js.ObjectStore(ctx, delivery.ArtifactBucket)
	if err != nil {
		return netbirdStageReply{}, err
	}
	name := "sha256-" + request.Digest
	if err := verifyNetBirdArtifact(ctx, js, store, request.Digest, request.Architecture, request.Size); err != nil {
		return netbirdStageReply{}, err
	}
	if _, err := netbirdStagePin(services, request); err != nil {
		return netbirdStageReply{}, err
	}
	if err := fencer.Guard(ctx, envelope.Epoch); err != nil {
		return netbirdStageReply{}, err
	}
	legacy, err := conn.JetStream()
	if err != nil {
		return netbirdStageReply{}, err
	}
	// Even an existing object is touched: a collector that chose it before
	// this pin became active must not delete the new reference afterward.
	if err := artifact.Touch(ctx, legacy, delivery.ArtifactBucket, name); err != nil {
		return netbirdStageReply{}, err
	}
	if err := fencer.Guard(ctx, envelope.Epoch); err != nil {
		return netbirdStageReply{}, err
	}
	if _, err := netbirdStagePin(services, request); err != nil {
		return netbirdStageReply{}, err
	}
	reply.Staged = true
	return reply, nil
}

func verifyCellRequest(wire []byte, policy signerPolicy, fencer authority.Fencer) (protocol.Envelope, string, error) {
	var envelope protocol.Envelope
	if err := protocol.DecodeStrict(wire, &envelope, maxRegistrationWireBytes); err != nil {
		return protocol.Envelope{}, "", err
	}
	trusted, ok := policy.trusted(envelope.KeyID)
	if !ok || trusted.Actor != envelope.Actor {
		return protocol.Envelope{}, "", errors.New("operator request signer is untrusted")
	}
	if err := protocol.VerifyEnvelope(envelope, protocol.EnvelopeScope{Region: policy.cell, Kind: envelope.Kind,
		Actor: trusted.Actor, OperationID: envelope.OperationID, Generation: envelope.Generation, Epoch: envelope.Epoch,
	}, trusted.PublicKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: time.Minute, ClockSkew: 30 * time.Second}); err != nil {
		return protocol.Envelope{}, "", err
	}
	if envelope.Epoch == 0 || fencer.Current().Epoch != envelope.Epoch {
		return protocol.Envelope{}, "", authority.ErrFenced
	}
	return envelope, trusted.Actor, nil
}

func (n *netbirdRollout) artifactsInUse(ctx context.Context) ([]delivery.ArtifactUse, error) {
	var uses []delivery.ArtifactUse
	add := func(pin *cellspec.NetBird) {
		if pin != nil {
			for _, digest := range []string{pin.Pin.Archives.Arm64.BinarySHA256, pin.Pin.Archives.AMD64.BinarySHA256} {
				uses = append(uses, delivery.ArtifactUse{Digest: digest, Role: "netbird", Environment: n.cell})
			}
		}
	}
	add(n.services.netbird())
	var record network.Record
	if err := n.load(ctx, netbirdRecordKey, &record); err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	if record.ID != "" && record.Phase != "done" {
		add(&cellspec.NetBird{Pin: record.Target.Pin})
	}
	return uses, nil
}

func (r *specRegistry) netbird() *cellspec.NetBird {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.current.NetBird
}

// A spec amendment cannot abandon a node already drained or changed. Finish
// its persisted target before using the new pin or disabling management.
func (n *netbirdRollout) target(ctx context.Context) (*cellspec.NetBird, error) {
	var record network.Record
	if err := n.load(ctx, netbirdRecordKey, &record); err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	if record.ID != "" && record.Phase != "done" && (record.Phase != "failed" || !record.RecoveryComplete) {
		return &cellspec.NetBird{Pin: record.Target.Pin, Enrollment: record.Target.Enrollment}, nil
	}
	return n.services.netbird(), nil
}

type netbirdRollout struct {
	cell             string
	fence            *releaseFence
	services         *specRegistry
	nodes            *nodeOps
	key              ed25519.PrivateKey
	cfg              Config
	fleet            oci.Fleet
	artifacts        jetstream.ObjectStore
	conn             *nats.Conn
	runtime          *natscell.Runtime
	managedAddresses map[string]string
	observed         time.Time
	artifactMu       sync.Mutex
	verifiedMetadata [2][]byte
}

func (n *netbirdRollout) load(ctx context.Context, key string, value any) error {
	if key == netbirdRecordKey || strings.HasPrefix(key, "netbird.command.") {
		return n.loadIntent(ctx, key, value)
	}
	return n.fence.loadJSON(ctx, key, value)
}

func (n *netbirdRollout) saveAt(ctx context.Context, epoch uint64, key string, value any) error {
	if !strings.HasPrefix(key, "netbird.status.") {
		return errors.New("NetBird intent requires a conditional authority commit")
	}
	wire, err := json.Marshal(value)
	if err != nil {
		return err
	}
	if err := n.fence.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err = n.fence.kv.Put(ctx, key, wire)
	return err
}

