func snapshotNetBirdStage(ctx context.Context, path, architecture string) (*os.File, string, int64, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", 0, err
	}
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, "", 0, err
	}
	source := os.NewFile(uintptr(fd), path)
	defer source.Close()
	info, err := source.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Size() < 64 || info.Size() > client.MaxBinaryBytes {
		return nil, "", 0, errors.New("NetBird staging source must be a bounded regular ELF executable")
	}
	snapshot, err := os.CreateTemp("", "ts-netbird-upload-*")
	if err != nil {
		return nil, "", 0, err
	}
	discard := func(err error) (*os.File, string, int64, error) {
		_ = snapshot.Close()
		_ = os.Remove(snapshot.Name())
		return nil, "", 0, err
	}
	size, err := io.Copy(snapshot, io.LimitReader(source, client.MaxBinaryBytes+1))
	if err != nil || size < 64 || size > client.MaxBinaryBytes {
		return discard(errors.Join(errors.New("cannot snapshot bounded NetBird staging source"), err))
	}
	digest, err := client.SHA256(snapshot.Name())
	if err != nil {
		return discard(err)
	}
	if err := client.VerifyBinary(snapshot.Name(), digest, architecture); err != nil {
		return discard(err)
	}
	if _, err := snapshot.Seek(0, io.SeekStart); err != nil {
		return discard(err)
	}
	if err := ctx.Err(); err != nil {
		return discard(err)
	}
	return snapshot, digest, size, nil
}

func VerifyBinary(path, expected, architecture string) error {
	return verifyBinaryLimit(path, expected, architecture, MaxBinaryBytes)
}

func verifyBinaryLimit(path, expected, architecture string, maximum int64) error {
	if !SHA256Pattern.MatchString(expected) {
		return errors.New("NetBird binary SHA-256 must be 64 lowercase hex characters")
	}
	f, e := openBoundedFileLimit(path, 64, maximum)
	if e != nil {
		return e
	}
	defer f.Close()
	var header [64]byte
	if _, e = io.ReadFull(f, header[:]); e != nil {
		return e
	}
	machine := uint16(183)
	if architecture == "amd64" {
		machine = 62
	} else if architecture != "arm64" {
		return errors.New("unsupported architecture")
	}
	if string(header[:7]) != "\x7fELF\x02\x01\x01" || (binary.LittleEndian.Uint16(header[16:]) != 2 && binary.LittleEndian.Uint16(header[16:]) != 3) || binary.LittleEndian.Uint16(header[18:]) != machine || binary.LittleEndian.Uint32(header[20:]) != 1 || binary.LittleEndian.Uint16(header[52:]) != 64 {
		return fmt.Errorf("NetBird binary must be an ELF64 little-endian %s executable", architecture)
	}
	h := sha256.New()
	h.Write(header[:])
	n, e := io.Copy(h, io.LimitReader(f, maximum+1-int64(len(header))))
	if e != nil {
		return e
	}
