func netbirdManagementLoop(control authority.Fencer) manager.Loop {
	return manager.Automatic(control, func(ctx context.Context) (vaultsecret.Ref, error) {
		local, err := foundationDiscovery(ctx)
		if err != nil {
			return vaultsecret.Ref{}, err
		}
		foundation, err := local.foundations.Resolve(ctx, "GRU")
		if err != nil {
			return vaultsecret.Ref{}, err
		}
		target, err := foundation.VaultTarget()
		if err != nil {
			return vaultsecret.Ref{}, err
		}
		return vaultsecret.Ref{Vault: target.VaultID, Name: "gru-1-netbird-admin-pat"}, nil
	}, log.Printf)
}

func Automatic(fencer authority.Fencer, credential func(context.Context) (vaultsecret.Ref, error),
	logf func(string, ...any),
) Loop {
	return Loop{Authority: fencer, Desired: GRU(), Logf: logf, Token: func(ctx context.Context) ([]byte, error) {
		if credential == nil {
			return nil, errors.New("NetBird management pending GRU foundation")
		}
		ref, err := credential(ctx)
		if err != nil {
			return nil, errors.New("NetBird management pending GRU foundation credential")
		}
		if ref.Name != "gru-1-netbird-admin-pat" || !strings.HasPrefix(ref.Vault, "ocid1.vault.oc1.sa-saopaulo-1.") {
			return nil, errors.New("NetBird management credential does not belong to the GRU foundation")
		}
		values, err := vaultsecret.ReadCurrentRefs(ctx, map[string]vaultsecret.Ref{"NETBIRD_ADMIN_PAT": ref})
		if err != nil {
			return nil, errors.New("NetBird management pending GRU Vault credential")
		}
		token := []byte(values["NETBIRD_ADMIN_PAT"].Value())
		if !netbird.ValidAdminPAT(token) {
			clear(token)
			return nil, errors.New("NetBird management Vault credential has an invalid shape")
		}
		return token, nil
	}}
}

func (l Loop) withDefaults() Loop {
	if l.Interval <= 0 {
		l.Interval = defaultLoopInterval
	}
	if l.ManagementURL == "" {
		l.ManagementURL = DefaultManagementURL
	}
	if l.newAPI == nil {
		l.newAPI = NewAPI
	}
	// A loop without a leadership check must never mutate the manager, so a
	// nil Leader means "not the leader" rather than "always lead": every
	// controller of a cell would otherwise reconcile concurrently.
	if l.Leader == nil {
		l.Leader = func() bool { return false }
	}
	if l.Logf == nil {
		l.Logf = func(string, ...any) {}
	}
	return l
}

// Run reconciles until ctx ends.
func (l Loop) Run(ctx context.Context) {
	l = l.withDefaults()
	// Let the controller settle before the first cycle.
	delay := l.initialDelay
	if delay <= 0 {
		delay = jitter(30 * time.Second)
	}
	retry := firstRetry
	warned := map[string]bool{}
	for {
		ctx := observability.StartTrace(ctx)
		timer := time.NewTimer(delay)
		select {
		case <-ctx.Done():
			timer.Stop()
			return
		case <-timer.C:
		}
		if !l.leading() {
			delay, retry = jitter(l.Interval), firstRetry
			continue
		}
		if err := l.cycle(ctx, warned); err != nil {
			if ctx.Err() != nil {
				return
			}
			l.Logf("NetBird management failed, retrying in %s: %v", retry, err)
			delay, retry = jitter(retry), min(retry*2, maxRetry)
			continue
		}
		delay, retry = jitter(l.Interval), firstRetry
	}
}

