func fenceKV(t *testing.T) jetstream.KeyValue {
	t.Helper()
	kv, _, _ := fenceBroker(t)
	return kv
}

func fenceBroker(t *testing.T) (jetstream.KeyValue, *nats.Conn, jetstream.JetStream) {
	t.Helper()
	srv, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, JetStream: true, StoreDir: t.TempDir()})
	if err != nil {
		t.Fatal(err)
	}
	srv.Start()
	t.Cleanup(srv.Shutdown)
	if !srv.ReadyForConnections(5 * time.Second) {
		t.Fatal("NATS did not start")
	}
	conn, err := nats.Connect(srv.ClientURL())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	kv, err := js.CreateKeyValue(t.Context(), jetstream.KeyValueConfig{Bucket: "TS_RELEASE_CHANNEL"})
	if err != nil {
		t.Fatal(err)
	}
	return kv, conn, js
}

func (l *fenceLease) ReadNetBirdState(context.Context) (authority.LogEntry, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.netbird.Sequence == 0 {
		return authority.LogEntry{}, authority.ErrNotFound
	}
	entry := l.netbird
	entry.Payload = slices.Clone(entry.Payload)
	return entry, nil
}

func (l *fenceLease) CommitNetBirdState(ctx context.Context, epoch uint64, operation string, expected uint64, wire []byte) (uint64, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if err := ctx.Err(); err != nil {
		return 0, err
	}
	if l.lost || epoch != 3 {
		return 0, authority.ErrFenced
	}
	if l.netbird.Sequence != expected {
		return 0, authority.ErrConflict
	}
	l.netbird = authority.LogEntry{Epoch: epoch, Sequence: expected + 1, OperationID: operation, Payload: slices.Clone(wire)}
	return l.netbird.Sequence, nil
}

func saveNetBirdTestRecord(ctx context.Context, n *netbirdRollout, epoch uint64, record network.Record) error {
	state, err := n.state(ctx)
	if err != nil {
		return err
	}
	next := state
	if state.Record.ID != record.ID || state.Record.Node != record.Node {
		next.Command = network.Command{}
	}
	next.Record = record
	return n.commitStateAt(ctx, epoch, &state, next)
}

func saveNetBirdTestAdmission(ctx context.Context, n *netbirdRollout, epoch uint64, record network.Record) error {
	state, err := n.state(ctx)
	if err != nil {
		return err
	}
	return n.saveRecordAt(ctx, epoch, &state, record)
}

// fenceLease is the leader's lease; Guard fails once lost.
type fenceLease struct {
	mu   sync.Mutex
	lost bool
	// lose, when set, loses the lease after that many guards.
	lose, guards int
	netbird      authority.LogEntry
}

func (l *fenceLease) Current() authority.Snapshot {
	l.mu.Lock()
	defer l.mu.Unlock()
	return authority.Snapshot{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV", Ready: true, Leader: !l.lost, Epoch: 3, Revision: 1, ExpiresAt: time.Now().Add(time.Hour)}
}

func (l *fenceLease) Guard(_ context.Context, epoch uint64) error {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.guards++
	if l.lose > 0 && l.guards >= l.lose {
		l.lost = true
	}
	if l.lost || epoch != 3 {
		return authority.ErrFenced
	}
	return nil
}

type disappearingNetBirdStatusKV struct {
	jetstream.KeyValue
	key string
}

func (k disappearingNetBirdStatusKV) Get(ctx context.Context, key string) (jetstream.KeyValueEntry, error) {
	if key == k.key {
		if err := k.KeyValue.Delete(ctx, key); err != nil {
			return nil, err
		}
	}
	return k.KeyValue.Get(ctx, key)
}

